<?php require __DIR__.'/layout.php';$rows=db()->query("SELECT * FROM achievements WHERE published=1 ORDER BY sort_order,id DESC")->fetchAll();site_header('Campeonatos');?>
<main id="conteudo-principal" class="content-page"><header class="page-banner"><span>ORGULHO E EXCELÊNCIA</span><h1>Vitórias e Campeonatos</h1><p>Registro das conquistas, classificações e participações marcantes da BAMAB.</p></header>
<div class="achievement-grid"><?php foreach($rows as $r):?><article class="achievement-card"><?php if($r['image_path']):?><img src="<?=e($r['image_path'])?>" alt="<?=e($r['title'])?>"><?php endif;?><div><span><?=e($r['year'])?></span><h3><?=e($r['title'])?></h3><strong><?=e($r['result'])?></strong><small><?=e($r['competition'])?></small><p><?=e($r['description'])?></p></div></article><?php endforeach;?></div><?php if(!$rows):?><div class="empty-public">As conquistas serão cadastradas pelo Admin.</div><?php endif;?></main><?php site_footer();?>